// =====================================================
// LOCATION + MOVING SHIPMENT ROUTE
// =====================================================


// =====================================================
// FIXED START LOCATION
// =====================================================

const START_LAT = 28.3262438;
const START_LON = 30.7054304;


// =====================================================
// FIXED DESTINATION
// =====================================================

const DEST_LAT = 28.3262814;
const DEST_LON = 30.705432;


// =====================================================
// ARRIVAL RADIUS
// =====================================================

const RADIUS = 7; // meters


// =====================================================
// GET GPS DATA
// =====================================================

let data = msg.payload;

let lat = Number(data.lat);
let lon = Number(data.lon);

if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    node.warn("Invalid GPS coordinates");
    return null;
}


// =====================================================
// DISTANCE CALCULATION
// =====================================================

function distanceInMeters(lat1, lon1, lat2, lon2) {

    const EARTH_RADIUS = 6371000;

    const dLat =
        (lat2 - lat1) * Math.PI / 180;

    const dLon =
        (lon2 - lon1) * Math.PI / 180;

    const a =
        Math.sin(dLat / 2) *
        Math.sin(dLat / 2) +

        Math.cos(lat1 * Math.PI / 180) *
        Math.cos(lat2 * Math.PI / 180) *

        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);

    const c =
        2 * Math.atan2(
            Math.sqrt(a),
            Math.sqrt(1 - a)
        );

    return EARTH_RADIUS * c;
}


// =====================================================
// DISTANCE TO DESTINATION
// =====================================================

let distance = distanceInMeters(
    lat,
    lon,
    DEST_LAT,
    DEST_LON
);


// =====================================================
// ARRIVAL STATUS WITH LOCK
// =====================================================

let previousStatus = flow.get("shipmentStatus") || "IN_TRANSIT";

let status;

if (previousStatus === "ARRIVED") {

    // Once arrived, stay ARRIVED.
    status = "ARRIVED";

} else if (distance <= RADIUS) {

    // First time entering the destination radius.
    status = "ARRIVED";

} else {

    status = "IN_TRANSIT";
}

// =====================================================
// GET EXISTING SHIPMENT ROUTE
// =====================================================

let route = flow.get("shipmentRoute");


// =====================================================
// INITIALIZE ROUTE
// =====================================================

// IMPORTANT:
// The route starts with the START point.
// This does NOT create a line to DESTINATION.
// The destination is only a separate marker.

if (!route || !Array.isArray(route) || route.length === 0) {

    route = [
        [
            START_LAT,
            START_LON
        ]
    ];
}


// =====================================================
// ADD CURRENT SHIPMENT LOCATION
// =====================================================

// Add the current location only if it changed.

let lastPoint = route[route.length - 1];

if (
    !lastPoint ||
    Math.abs(lastPoint[0] - lat) > 0.000001 ||
    Math.abs(lastPoint[1] - lon) > 0.000001
) {

    route.push([
        lat,
        lon
    ]);
}


// =====================================================
// SAVE ROUTE
// =====================================================

// NEVER CLEAR THE ROUTE.
// It remains after ARRIVED.

flow.set(
    "shipmentRoute",
    route
);


// =====================================================
// FIXED START MARKER
// =====================================================

let startPoint = {

    name: "START",

    lat: START_LAT,

    lon: START_LON,

    icon: "flag",

    layer: "Fixed Points"

};


// =====================================================
// FIXED DESTINATION MARKER
// =====================================================

let destinationPoint = {

    name: "DESTINATION",

    lat: DEST_LAT,

    lon: DEST_LON,

    icon: "flag",

    layer: "Fixed Points"

};


// =====================================================
// MOVING SHIPMENT
// =====================================================

let truck = {

    name: "Shipment 001",

    lat: lat,

    lon: lon,

    icon: "truck",

    layer: "Shipment"

};


// =====================================================
// ACTUAL SHIPMENT ROUTE
// =====================================================

// This line contains ONLY the points where
// the shipment actually moved.

let routeLine = {

    name: "Shipment Route",

    line: route,

    layer: "Route"

};


// =====================================================
// WORLD MAP OUTPUT
// =====================================================

let mapMsg = {

    payload: [

        startPoint,

        destinationPoint,

        truck,

        routeLine

    ]

};


// =====================================================
// GAUGE OUTPUT
// =====================================================

let gaugeMsg = {

    payload: Number(
        distance.toFixed(2)
    ),

    status: status,

    latitude: lat,

    longitude: lon

};


// =====================================================
// TEXT OUTPUT
// =====================================================

let textMsg = {

    payload:
        status +
        " | Distance: " +
        distance.toFixed(2) +
        " m"

};


// =====================================================
// NODE STATUS
// =====================================================

node.status({

    fill:
        status === "ARRIVED"
            ? "green"
            : "blue",

    shape: "dot",

    text:
        status +
        " | " +
        distance.toFixed(1) +
        " m"

});


// =====================================================
// ARRIVAL MESSAGE
// =====================================================

if (status === "ARRIVED") {

    node.warn(
        "PACKAGE ARRIVED! Distance = " +
        distance.toFixed(2) +
        " meters"
    );

}


// =====================================================
// SAVE CURRENT DATA
// =====================================================

flow.set(
    "shipmentStatus",
    status
);

flow.set(
    "shipmentDistance",
    distance
);

flow.set(
    "shipmentLatitude",
    lat
);

flow.set(
    "shipmentLongitude",
    lon
);


// =====================================================
// RETURN 3 OUTPUTS
// =====================================================

// Output 1 → Worldmap
// Output 2 → Gauge
// Output 3 → Text

return [

    mapMsg,

    gaugeMsg,

    textMsg

];
